/* data/cs-c/cs-12-02.js - GENERATED by tools/build.py from data/cs/cs-12-02.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-02"] = [{"id":"cs-12-02-01","kind":"short","q":"What is data ?","marks":3,"src":["Guide ch.2 Data Structure, Q.1"],"model":[{"t":"Data means raw facts and figures: numbers, words or symbols that have not been processed.","m":1},{"t":"Alone, data does not tell much. For example, 45, \"Amit\" and 12 are data.","m":1},{"t":"When data is processed it becomes information.","m":1}]},{"id":"cs-12-02-02","kind":"short","q":"What are group items ?","marks":3,"src":["Guide ch.2 Data Structure, Q.2"],"model":[{"t":"A group item is a data item that can be divided into smaller parts called subitems.","m":1},{"t":"Example: the name of a student can be divided into first name, middle name and surname.","m":1},{"t":"Another example is a date, which divides into day, month and year.","m":1}]},{"id":"cs-12-02-03","kind":"short","q":"What is information ?","marks":3,"src":["Guide ch.2 Data Structure, Q.3"],"model":[{"t":"Information is data that has been processed so that it has meaning and is useful for taking decisions.","m":1},{"t":"Example: the marks of a class are data; the class average or the topper list is information.","m":1},{"t":"The same data can give different information when it is processed in different ways.","m":1}]},{"id":"cs-12-02-04","kind":"short","q":"What is file ?","marks":3,"src":["Guide ch.2 Data Structure, Q.4"],"model":[{"t":"A file is a collection of related records.","m":1},{"t":"Example: a school keeps one file of student records; every student is one record in it.","m":1},{"t":"Files are stored on disk and are used to keep data for a long time.","m":1}]},{"id":"cs-12-02-05","kind":"short","q":"What is record ?","marks":3,"src":["Guide ch.2 Data Structure, Q.5"],"model":[{"t":"A record is a collection of related data items (fields) that describe one thing or one person.","m":1},{"t":"Example: roll number, name and marks of one student form one record.","m":1},{"t":"The fields of a record can be of different types.","m":1}]},{"id":"cs-12-02-06","kind":"short","q":"What is primary key ?","marks":3,"src":["Guide ch.2 Data Structure, Q.6"],"model":[{"t":"A primary key is a field (or a group of fields) whose value is different for every record of a file.","m":1},{"t":"So the primary key finds one record without any doubt.","m":1},{"t":"Example: the roll number of a student, because no two students have the same one.","m":1}]},{"id":"cs-12-02-07","kind":"short","q":"What is data structure ?","marks":3,"src":["Guide ch.2 Data Structure, Q.7"],"model":[{"t":"A data structure is a way of arranging and storing data in the computer memory so that it can be used efficiently.","m":1},{"t":"It includes the data and the operations that can be done on it.","m":1},{"t":"Examples: array, linked list, stack, queue and tree.","m":1}]},{"id":"cs-12-02-08","kind":"short","q":"What operations can be performed on data structure ? Briefly describe them.","marks":4,"src":["Guide ch.2 Data Structure, Q.8"],"model":[{"t":"Traversing: visiting every element once to process it. Searching: finding the place of a given element.","m":1},{"t":"Inserting: adding a new element. Deleting: removing an element.","m":1},{"t":"Sorting: arranging the elements in ascending or descending order.","m":1},{"t":"Merging: joining two sorted lists into one sorted list.","m":1}]},{"id":"cs-12-02-09","kind":"short","q":"What is algorithm ?","marks":3,"src":["Guide ch.2 Data Structure, Q.9"],"model":[{"t":"An algorithm is a finite list of steps, in a clear order, that solves a problem.","m":1},{"t":"Each step is simple and exact, and the algorithm ends after a limited number of steps.","m":1},{"t":"It is written before the program, in plain language or in algorithmic notation.","m":1}]},{"id":"cs-12-02-10","kind":"short","q":"Describe conditional structure.","marks":4,"src":["Guide ch.2 Data Structure, Q.10"],"model":[{"t":"In a conditional structure the steps to be done depend on a condition that is tested.","m":1},{"t":"If-then form: If condition, then [do these steps].","m":1},{"t":"If-then-else form: If condition, then [module A], else [module B]. Only one of the two modules is done.","m":1},{"t":"Example: If marks >= 35 then print \"Pass\" else print \"Fail\".","m":1}]},{"id":"cs-12-02-11","kind":"short","q":"Describe logic of repeat while structure.","marks":4,"src":["Guide ch.2 Data Structure, Q.11"],"model":[{"t":"The repeat while structure repeats a set of steps again and again as long as a condition is true.","m":1},{"t":"Form: Repeat while condition: [steps], and the condition is tested before each round.","m":1},{"t":"When the condition becomes false, the loop stops and the next step after it is done.","m":1},{"t":"Something inside the loop must change the condition, or the loop never ends.","m":1}]},{"id":"cs-12-02-12","kind":"short","q":"What are arrays ?","marks":3,"src":["Guide ch.2 Data Structure, Q.12"],"model":[{"t":"An array is a linear list of a fixed number of elements of the same type (homogeneous).","m":1},{"t":"The elements are kept in consecutive memory locations.","m":1},{"t":"Each element is reached by its subscript (index), as A[1], A[2], and so on.","m":1}]},{"id":"cs-12-02-13","kind":"short","q":"How arrays are represented in memory ?","marks":4,"src":["Guide ch.2 Data Structure, Q.13"],"model":[{"t":"The elements of a linear array are stored one after another in consecutive memory locations.","m":1},{"t":"The computer remembers only the address of the first element, called the base address, Base(A).","m":1},{"t":"The address of any element is found by: LOC(A[K]) = Base(A) + w * (K - LB), where w is the size of one element and LB is the lower bound.","m":1},{"t":"So any element can be reached directly; this is called direct (random) access.","m":1}]},{"id":"cs-12-02-14","kind":"prog","q":"What is traversing a linear array ? Write algorithm for traversing a linear array.","marks":4,"src":["Guide ch.2 Data Structure, Q.14"],"model":[{"t":"Traversing means visiting every element of the array exactly once and processing it (for example printing it).","m":1},{"t":"The algorithm sets a counter to the lower bound and moves it step by step to the upper bound.","m":1},{"t":"At each step it applies the process to the element and adds 1 to the counter.","m":1},{"t":"Algorithm steps are written clearly and the algorithm ends.","m":1}],"code":"Algorithm: traverse linear array LA with lower bound LB and upper bound UB\nStep 1: Set K = LB\nStep 2: Repeat steps 3 and 4 while K <= UB\nStep 3:     Apply PROCESS to LA[K]\nStep 4:     Set K = K + 1\nStep 5: Exit"},{"id":"cs-12-02-15","kind":"prog","q":"Write algorithm for inserting an element into array.","marks":4,"src":["Guide ch.2 Data Structure, Q.15"],"model":[{"t":"Insert ITEM at position K in the array LA that has N elements.","m":1},{"t":"First make room: move the elements from position K onwards one place to the right, starting from the last one.","m":1},{"t":"Put ITEM at position K and increase N by 1.","m":1},{"t":"Steps are in the right order and the algorithm ends.","m":1}],"code":"Algorithm: insert ITEM at position K in LA with N elements\nStep 1: Set J = N\nStep 2: Repeat steps 3 and 4 while J >= K\nStep 3:     Set LA[J + 1] = LA[J]\nStep 4:     Set J = J - 1\nStep 5: Set LA[K] = ITEM\nStep 6: Set N = N + 1\nStep 7: Exit"},{"id":"cs-12-02-16","kind":"prog","q":"Write algorithm for deleting an element from array.","marks":4,"src":["Guide ch.2 Data Structure, Q.16"],"model":[{"t":"Delete the element at position K from the array LA that has N elements.","m":1},{"t":"Keep the deleted element in ITEM, then move every element after position K one place to the left.","m":1},{"t":"Decrease N by 1.","m":1},{"t":"Steps are in the right order and the algorithm ends.","m":1}],"code":"Algorithm: delete the element at position K from LA with N elements\nStep 1: Set ITEM = LA[K]\nStep 2: Set J = K\nStep 3: Repeat steps 4 and 5 while J < N\nStep 4:     Set LA[J] = LA[J + 1]\nStep 5:     Set J = J + 1\nStep 6: Set N = N - 1\nStep 7: Exit"},{"id":"cs-12-02-17","kind":"short","q":"What is sorting ?","marks":3,"src":["Guide ch.2 Data Structure, Q.17"],"model":[{"t":"Sorting means arranging the data in a particular order: ascending (small to large) or descending (large to small).","m":1},{"t":"Names can be sorted in alphabetical order, numbers in numerical order.","m":1},{"t":"Sorted data is easier and faster to search. Examples: bubble sort, selection sort.","m":1}]},{"id":"cs-12-02-18","kind":"prog","q":"Write bubble sort algorithm for sorting.","marks":5,"src":["Guide ch.2 Data Structure, Q.18"],"model":[{"t":"Bubble sort compares each pair of neighbouring elements and swaps them if they are in the wrong order.","m":1},{"t":"In each pass the largest remaining element moves to the end, like a bubble rising.","m":1},{"t":"The passes are repeated N - 1 times.","m":1},{"t":"The comparison and the swap inside each pass are written correctly.","m":1},{"t":"Steps are in the right order and the algorithm ends.","m":1}],"code":"Algorithm: bubble sort of A with N elements (ascending)\nStep 1: Repeat steps 2 and 3 for K = 1 to N - 1\nStep 2:     Set PTR = 1\nStep 3:     Repeat while PTR <= N - K\n               (a) If A[PTR] > A[PTR + 1], then interchange A[PTR] and A[PTR + 1]\n               (b) Set PTR = PTR + 1\nStep 4: Exit"},{"id":"cs-12-02-19","kind":"short","q":"What is searching ?","marks":3,"src":["Guide ch.2 Data Structure, Q.19"],"model":[{"t":"Searching means finding the place (location) of a given item in a list or a data structure.","m":1},{"t":"If the item is found the search is successful; if not, it is unsuccessful.","m":1},{"t":"Two methods are linear search and binary search.","m":1}]},{"id":"cs-12-02-20","kind":"prog","q":"Write algorithm for linear search.","marks":4,"src":["Guide ch.2 Data Structure, Q.20"],"model":[{"t":"Linear (sequential) search compares the item with the elements one by one from the start.","m":1},{"t":"It stops when the item is found or the end of the array is reached.","m":1},{"t":"If found, the location is given; if not, the location is set to 0 (not found).","m":1},{"t":"Steps are in the right order and the algorithm ends.","m":1}],"code":"Algorithm: linear search for ITEM in LA with N elements\nStep 1: Set K = 1 and LOC = 0\nStep 2: Repeat steps 3 and 4 while K <= N and LOC = 0\nStep 3:     If LA[K] = ITEM, then Set LOC = K\nStep 4:     Set K = K + 1\nStep 5: If LOC = 0, print \"ITEM is not in the array\"; else print LOC\nStep 6: Exit"},{"id":"cs-12-02-21","kind":"prog","q":"Write algorithm for binary search.","marks":5,"src":["Guide ch.2 Data Structure, Q.21"],"model":[{"t":"Binary search works only on a sorted array.","m":1},{"t":"It compares ITEM with the middle element and throws away the half in which ITEM cannot be.","m":1},{"t":"BEG, END and MID are set and updated correctly in each round.","m":1},{"t":"The loop ends when ITEM is found or BEG becomes greater than END.","m":1},{"t":"The result (location or not found) is given and the algorithm ends.","m":1}],"code":"Algorithm: binary search for ITEM in sorted array A, lower bound LB, upper bound UB\nStep 1: Set BEG = LB, END = UB, MID = INT((BEG + END) / 2)\nStep 2: Repeat steps 3 and 4 while BEG <= END and A[MID] != ITEM\nStep 3:     If ITEM < A[MID], then Set END = MID - 1\n            else Set BEG = MID + 1\nStep 4:     Set MID = INT((BEG + END) / 2)\nStep 5: If A[MID] = ITEM, then Set LOC = MID\n        else Set LOC = NULL (not found)\nStep 6: Exit"},{"id":"cs-12-02-22","kind":"short","q":"What is pointer ?","marks":3,"src":["Guide ch.2 Data Structure, Q.22"],"model":[{"t":"A pointer is a variable that holds the address (memory location) of another variable or element.","m":1},{"t":"It \"points\" to the place where the data is kept.","m":1},{"t":"Pointers are used to build linked lists and trees.","m":1}]},{"id":"cs-12-02-23","kind":"short","q":"What are pointer arrays ?","marks":3,"src":["Guide ch.2 Data Structure, Q.23"],"model":[{"t":"A pointer array is an array whose elements are pointers, that is, addresses of other data.","m":1},{"t":"Example: an array of pointers to long records, so only the short pointers are moved when the data is arranged.","m":1},{"t":"It saves memory and time when the records are of different lengths.","m":1}]},{"id":"cs-12-02-24","kind":"short","q":"How records are represented in memory ?","marks":4,"src":["Guide ch.2 Data Structure, Q.24"],"model":[{"t":"The fields of a record are kept one after another in consecutive memory locations.","m":1},{"t":"Every field has its own size, so the position of a field inside the record is fixed.","m":1},{"t":"Many records of one kind can be kept in an array of records, one after the other.","m":1},{"t":"A field of a record is found from the address of the record plus the position of the field.","m":1}]},{"id":"cs-12-02-25","kind":"short","q":"What is linked list ?","marks":3,"src":["Guide ch.2 Data Structure, Q.25"],"model":[{"t":"A linked list is a linear collection of items called nodes.","m":1},{"t":"Each node has two parts: the data (information) and a pointer to the next node.","m":1},{"t":"The last node has a null pointer. The list is reached through a start pointer.","m":1}]},{"id":"cs-12-02-26","kind":"short","q":"What are advantages of linked lists over lists ?","marks":4,"src":["Guide ch.2 Data Structure, Q.26"],"model":[{"t":"The size of a linked list can grow and shrink while the program runs; an array has a fixed size.","m":1},{"t":"Insertion and deletion are easy: only pointers are changed, and no element is moved.","m":1},{"t":"Memory is used as needed, so little memory is wasted.","m":1},{"t":"Nodes need not be in consecutive memory locations.","m":1}]},{"id":"cs-12-02-27","kind":"short","q":"How linked lists are represented in memory ?","marks":4,"src":["Guide ch.2 Data Structure, Q.27"],"model":[{"t":"A linked list uses two parallel arrays, INFO for the data and LINK for the pointer to the next node.","m":1},{"t":"A variable START holds the location of the first node.","m":1},{"t":"The last node has NULL in its LINK. The unused nodes are kept in a free storage list called AVAIL.","m":1},{"t":"A node is reached from START by following the LINK values one by one.","m":1}]},{"id":"cs-12-02-28","kind":"short","q":"What is tree ?","marks":3,"src":["Guide ch.2 Data Structure, Q.28"],"model":[{"t":"A tree is a non-linear data structure that shows a hierarchy, like a family tree.","m":1},{"t":"It has one top node called the root, and the other nodes are connected below it by branches.","m":1},{"t":"Every node except the root has exactly one parent. Nodes with no children are called leaves.","m":1}]},{"id":"cs-12-02-29","kind":"short","q":"What is binary tree ?","marks":3,"src":["Guide ch.2 Data Structure, Q.29"],"model":[{"t":"A binary tree is a tree in which each node has at most two children.","m":1},{"t":"The two children are called the left child and the right child.","m":1},{"t":"A binary tree can also be empty. It is used for searching, sorting and for expressions.","m":1}]},{"id":"cs-12-02-30","kind":"short","q":"What is extended 2-tree ?","marks":3,"src":["Guide ch.2 Data Structure, Q.30"],"model":[{"t":"An extended 2-tree is a binary tree in which every node has either 0 or 2 children.","m":1},{"t":"It is made by adding special external nodes in every place where a child was missing.","m":1},{"t":"The original nodes are called internal nodes and the added nodes are external nodes.","m":1}]},{"id":"cs-12-02-31","kind":"short","q":"How algebraic expressions are represented by binary tree ?","marks":4,"src":["Guide ch.2 Data Structure, Q.31"],"model":[{"t":"The operators of the expression are put in the internal nodes and the operands in the leaves.","m":1},{"t":"The operator of the last operation done is the root of the tree.","m":1},{"t":"Example: a + b * c has + at the root, a as its left child, and the subtree for b * c on the right.","m":1},{"t":"Brackets and the order of the operators decide the shape of the tree, and no brackets are needed in the tree.","m":1}]},{"id":"cs-12-02-32","kind":"short","q":"How binary trees are represented in memory ?","marks":4,"src":["Guide ch.2 Data Structure, Q.32"],"model":[{"t":"Linked representation: three parallel arrays are used. INFO holds the data, LEFT and RIGHT hold the locations of the left and right children.","m":1},{"t":"A variable ROOT holds the location of the root node. A NULL in LEFT or RIGHT means there is no child.","m":1},{"t":"Sequential representation: the tree is kept in one array. The root is at position 1, and the node at K has its children at 2K and 2K + 1.","m":1},{"t":"The positions of missing nodes are left empty (zero), as in the figure of the guide.","m":1}]},{"id":"cs-12-02-m33a","kind":"mcq","q":"Pin code number is ..............","marks":1,"src":["Guide ch.2 Data Structure, Q.33(a)"],"options":["group item","elementary item","subitem","none of these"],"ans":1,"why":"A pin code is one number that is not divided into smaller parts here, so it is an elementary item. A group item is one that divides into subitems, like a name."},{"id":"cs-12-02-m33b","kind":"mcq","q":"A record is collection of ..............","marks":1,"src":["Guide ch.2 Data Structure, Q.33(b)"],"options":["files","fields","arrays","none of these"],"ans":1,"why":"A record is made of related fields. A file is a collection of records."},{"id":"cs-12-02-m33c","kind":"mcq","q":"Accessing each element only once is called ..............","marks":1,"src":["Guide ch.2 Data Structure, Q.33(c)"],"options":["traversing","searching","inserting","deleting"],"ans":0,"why":"Visiting every element once to process it is traversing."},{"id":"cs-12-02-m33d","kind":"mcq","q":"The elements in array are ..............","marks":1,"src":["Guide ch.2 Data Structure, Q.33(d)"],"options":["homogeneous","non homogeneous","equal","none of these"],"ans":0,"why":"All the elements of an array are of the same type, so they are homogeneous. They need not be equal in value."},{"id":"cs-12-02-m33e","kind":"mcq","q":"Finding location of given element is called ..............","marks":1,"src":["Guide ch.2 Data Structure, Q.33(e)"],"options":["sorting","searching","traversing","none of these"],"ans":1,"why":"Finding where an item is kept is searching."},{"id":"cs-12-02-m33f","kind":"mcq","q":"Number of comparisons in binary search are .............. that of linear search","marks":1,"src":["Guide ch.2 Data Structure, Q.33(f)"],"options":["equal","greater than","less than","none of these"],"ans":2,"why":"Binary search halves the list at every step, so it needs fewer comparisons than linear search."},{"id":"cs-12-02-m33g","kind":"mcq","q":"Pointer variable contains ..............","marks":1,"src":["Guide ch.2 Data Structure, Q.33(g)"],"options":["address","float number","character","string"],"ans":0,"why":"A pointer holds the address of another variable."},{"id":"cs-12-02-m33h","kind":"mcq","q":"Record contains .............. data.","marks":1,"src":["Guide ch.2 Data Structure, Q.33(h)"],"options":["homogeneous","non homogeneous","same","none of these"],"ans":1,"why":"The fields of a record can be of different types (number, text and so on), so a record holds non homogeneous data. An array holds homogeneous data."},{"id":"cs-12-02-m33i","kind":"mcq","q":"Tree is .............. data structure.","marks":1,"src":["Guide ch.2 Data Structure, Q.33(i)"],"options":["linear","non linear","homogeneous","non homogeneous"],"ans":1,"why":"A tree shows a hierarchy with branches, not a single line, so it is a non linear data structure."},{"id":"cs-12-02-p901","kind":"mcq","q":"The maximum number of nodes is a binary tree of depth 6 is ..........","marks":1,"src":["HSC March 2022 Paper I, Q.1A(b)"],"options":["64","32","63","6"],"ans":2,"why":"A binary tree of depth d (counting levels from 1) holds at most 2 to the power d, minus 1 nodes. For d = 6 this is 64 - 1 = 63."},{"id":"cs-12-02-p902","kind":"mcq","q":"Data items that are divided into subitems are called as ..........","marks":1,"src":["HSC March 2023 Paper I, Q.1A(b)"],"options":["Group item","Elementry item","Nodes","Arrays"],"ans":0,"why":"A group item can be split into smaller items (for example a name into first name and surname). An elementary item cannot be split."},{"id":"cs-12-02-p903","kind":"short","q":"What is a Record ? Write any two distinguishing points between a Record and Linear Array.","marks":3,"src":["HSC March 2022 Paper I, Q.2A(b)"],"model":[{"t":"A record is a collection of related data items (fields), which can be of different types. Example: roll number, name and marks of a student.","m":1},{"t":"A record may hold items of different data types, but all the elements of a linear array have the same type.","m":1},{"t":"The items of a record have different names, while the elements of an array are reached by an index number.","m":1}]},{"id":"cs-12-02-p904","kind":"short","q":"Define the following terms with respect to binary tree:\ni) Depth of tree\nii) Degree of node\niii) Empty or Null tree","marks":3,"src":["HSC March 2022 Paper I, Q.3A(a)"],"model":[{"t":"Depth of a tree: the number of levels in the tree, that is the largest level number of its nodes (the length of the longest path from the root, plus one).","m":1},{"t":"Degree of a node: the number of children (subtrees) of the node. In a binary tree it is 0, 1 or 2.","m":1},{"t":"Empty (null) tree: a tree that has no node at all.","m":1}]},{"id":"cs-12-02-p905","kind":"prog","q":"Draw a binary tree structure for expression : E = (p – q) / [(r # s) + t].","marks":3,"src":["HSC March 2022 Paper I, Q.4A(c)"],"model":[{"t":"The operator of the lowest precedence, outside the brackets, is the division, so / is the root.","m":1},{"t":"The left subtree is the tree of (p - q): - with children p and q. The right subtree is the tree of ((r # s) + t): + with children the tree of (r # s) and t.","m":1},{"t":"The leaves are the operands p, q, r, s and t; every other node is an operator.","m":1}],"code":"            /\n          /   \\\n        -       +\n       / \\     / \\\n      p   q   #   t\n             / \\\n            r   s","figs":[{"f":"tree-e1","alt":"Binary tree of E = (p - q) / [(r # s) + t]","h":330}]},{"id":"cs-12-02-p906","kind":"short","q":"Define following terms regarding data structure :\ni) Entity\nii) Group item\niii) Elementary item","marks":3,"src":["HSC March 2023 Paper I, Q.1B(a)"],"model":[{"t":"Entity: a person, place, thing or event about which data is kept. Example: a student. Its properties are its attributes.","m":1},{"t":"Group item: a data item that can be divided into smaller items. Example: Name, divided into first name, middle name and surname.","m":1},{"t":"Elementary item: a data item that cannot be divided further. Example: roll number.","m":1}]},{"id":"cs-12-02-p907","kind":"prog","q":"What is Binary Tree ? Draw a bionary tree diagram of following mathematical expression :\nE = (a2 + bc2)/d","marks":3,"src":["HSC March 2023 Paper I, Q.1B(b)"],"model":[{"t":"A binary tree is a tree in which every node has at most two children, called the left child and the right child. It can also be empty.","m":1},{"t":"For E = (a2 + bc2) / d the root is /. Its right child is d. Its left child is + with children a2 and the product of b and c2.","m":1},{"t":"The squares are written as nodes with the power operator: a ^ 2 and c ^ 2. The diagram is drawn below.","m":1}],"code":"              /\n            /   \\\n          +       d\n         / \\\n       ^     *\n      / \\   / \\\n     a   2 b   ^\n              / \\\n             c   2","figs":[{"f":"tree-e2","alt":"Binary tree of E = (a2 + bc2) / d","h":360}]},{"id":"cs-12-02-p908","kind":"short","q":"Write three distinct differences between Array and Linked List.","marks":3,"src":["HSC March 2024 Paper I, Q.1B(b)"],"model":[{"t":"Size: an array has a fixed size set at the start. A linked list can grow and shrink while the program runs.","m":1},{"t":"Memory: array elements are stored in continuous locations. List nodes can be anywhere in memory and are joined by pointers.","m":1},{"t":"Insertion and deletion: in an array the other elements have to be shifted, which is slow. In a linked list only a pointer is changed. But an array element can be reached directly by its index, whereas a list must be walked from the start.","m":1}]},{"id":"cs-12-02-p909","kind":"prog","q":"What is Binary Tree ? Draw Binary Tree for following expression:\nY = (A+B)/ (CD)","marks":4,"src":["HSC March 2024 Paper I, Q.3B(a)"],"model":[{"t":"A binary tree is a tree in which each node has at most two children (a left and a right child).","m":1},{"t":"In Y = (A + B) / (C D) the division is the last operation done, so it is the root.","m":1},{"t":"The left subtree is + with children A and B.","m":1},{"t":"The right subtree is the product C * D (CD means C multiplied by D): * with children C and D.","m":1}],"code":"          /\n        /   \\\n      +       *\n     / \\     / \\\n    A   B   C   D","figs":[{"f":"tree-y","alt":"Binary tree of Y = (A + B) / (CD)","h":270}]}];
